ALTER TABLE incentive_plan ADD COLUMN created_by TEXT;
ALTER TABLE incentive_plan ADD COLUMN created_at TEXT;
CREATE TABLE incentive_plan_version(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,plan_id TEXT NOT NULL,revision_no INTEGER NOT NULL,target_version_id TEXT NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,timezone TEXT NOT NULL,role_code TEXT NOT NULL,channel TEXT NOT NULL,rules_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','submitted','approved','active','retired')),version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,submitted_by TEXT,approved_by TEXT,created_at TEXT NOT NULL,reason TEXT NOT NULL,preview_json TEXT,UNIQUE(organization_id,plan_id,revision_no),UNIQUE(organization_id,id));
CREATE TABLE incentive_enrollment(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,plan_version_id TEXT NOT NULL,user_id TEXT NOT NULL,role_code TEXT NOT NULL,channel TEXT NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,area_ids_json TEXT NOT NULL,target_items_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',UNIQUE(organization_id,plan_version_id,user_id));
CREATE TRIGGER incentive_enrollment_overlap BEFORE UPDATE OF status ON incentive_enrollment WHEN NEW.status='active' AND EXISTS(SELECT 1 FROM incentive_enrollment e WHERE e.organization_id=NEW.organization_id AND e.user_id=NEW.user_id AND e.id<>NEW.id AND e.status='active' AND e.period_start<=NEW.period_end AND e.period_end>=NEW.period_start) BEGIN SELECT RAISE(ABORT,'INCENTIVE_PRIMARY_OVERLAP'); END;
CREATE TRIGGER incentive_plan_locked BEFORE UPDATE OF rules_json,target_version_id,period_start,period_end,role_code,channel ON incentive_plan_version WHEN OLD.status IN('approved','active','retired') BEGIN SELECT RAISE(ABORT,'INCENTIVE_PLAN_IMMUTABLE'); END;
CREATE TRIGGER incentive_enrollment_locked BEFORE UPDATE OF user_id,target_items_json,area_ids_json,period_start,period_end,role_code,channel ON incentive_enrollment WHEN OLD.status='active' BEGIN SELECT RAISE(ABORT,'INCENTIVE_ENROLLMENT_IMMUTABLE'); END;
CREATE TABLE calculation_run(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,enrollment_id TEXT NOT NULL,plan_version_id TEXT NOT NULL,user_id TEXT NOT NULL,cutoff TEXT NOT NULL,source_hash TEXT NOT NULL,inputs_json TEXT NOT NULL,result_json TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER calculation_run_immutable BEFORE UPDATE ON calculation_run BEGIN SELECT RAISE(ABORT,'CALCULATION_RUN_IMMUTABLE'); END;
CREATE TRIGGER calculation_run_no_delete BEFORE DELETE ON calculation_run BEGIN SELECT RAISE(ABORT,'CALCULATION_RUN_IMMUTABLE'); END;
CREATE TABLE incentive_statement(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,enrollment_id TEXT NOT NULL,run_id TEXT NOT NULL,user_id TEXT NOT NULL,plan_version_id TEXT NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,revision_no INTEGER NOT NULL,previous_statement_id TEXT,status TEXT NOT NULL DEFAULT 'prepared' CHECK(status IN('prepared','under_review','finalized','exported','paid_confirmed','superseded')),review_flags_json TEXT NOT NULL DEFAULT '[]',entitlement_minor INTEGER,payable_delta_minor INTEGER,version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,submitted_by TEXT,finalized_by TEXT,created_at TEXT NOT NULL,finalized_at TEXT,dispute_deadline TEXT NOT NULL,payment_reference TEXT,UNIQUE(organization_id,enrollment_id,revision_no),UNIQUE(organization_id,run_id));
CREATE UNIQUE INDEX incentive_statement_open ON incentive_statement(organization_id,enrollment_id) WHERE status IN('prepared','under_review');
CREATE TRIGGER incentive_statement_amount_locked BEFORE UPDATE OF run_id,entitlement_minor,payable_delta_minor,previous_statement_id,period_start,period_end ON incentive_statement BEGIN SELECT RAISE(ABORT,'STATEMENT_INPUT_IMMUTABLE'); END;
CREATE TABLE statement_dispute(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,statement_id TEXT NOT NULL,user_id TEXT NOT NULL,reason TEXT NOT NULL,evidence TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',resolution TEXT,resolved_by TEXT,source_run_id TEXT,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE incentive_export(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,statement_ids_json TEXT NOT NULL,payload_json TEXT NOT NULL,checksum TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(organization_id,checksum));
CREATE TRIGGER incentive_export_immutable BEFORE UPDATE ON incentive_export BEGIN SELECT RAISE(ABORT,'EXPORT_IMMUTABLE'); END;
CREATE TABLE payment_confirmation(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,statement_id TEXT NOT NULL,reference TEXT NOT NULL,amount_minor INTEGER NOT NULL,confirmed_by TEXT NOT NULL,confirmed_at TEXT NOT NULL,UNIQUE(organization_id,statement_id),UNIQUE(organization_id,reference));
CREATE TABLE sensitive_access(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,actor_id TEXT NOT NULL,resource TEXT NOT NULL,resource_id TEXT NOT NULL,occurred_at TEXT NOT NULL);
CREATE INDEX statement_owner_period ON incentive_statement(organization_id,user_id,period_start);
CREATE INDEX incentive_enrollment_owner ON incentive_enrollment(organization_id,user_id,status);
